argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32CommonDlg {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr hDlg, int nIDDlgItem);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern bool SetWindowText(IntPtr hWnd, string lpString);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
$script:dlg=[IntPtr]::Zero
$cb=[W32CommonDlg+EnumWindowsProc]{
  param($h,$l)
  $tsb=New-Object System.Text.StringBuilder 256
  $csb=New-Object System.Text.StringBuilder 128
  [void][W32CommonDlg]::GetWindowText($h,$tsb,$tsb.Capacity)
  [void][W32CommonDlg]::GetClassName($h,$csb,$csb.Capacity)
  if($tsb.ToString() -eq '開啟' -and $csb.ToString() -eq '#32770'){
    $script:dlg=$h
    return $false
  }
  return $true
}
[W32CommonDlg]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null
if($script:dlg -eq [IntPtr]::Zero){throw 'Threads Open dialog not found'}
[W32CommonDlg]::SetForegroundWindow($script:dlg)|Out-Null

$fileBox=[W32CommonDlg]::GetDlgItem($script:dlg,1148)
if($fileBox -eq [IntPtr]::Zero){throw 'Standard file-name control 1148 not found'}
$ok=[W32CommonDlg]::SetWindowText($fileBox,'C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg')
if(-not $ok){throw 'SetWindowText on file-name field failed'}
Start-Sleep -Milliseconds 300

$open=[W32CommonDlg]::GetDlgItem($script:dlg,1)
if($open -eq [IntPtr]::Zero){throw 'Standard Open button IDOK not found'}
[void][W32CommonDlg]::SendMessage($open,0x00F5,[IntPtr]::Zero,[IntPtr]::Zero)
Start-Sleep -Seconds 8

$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible after attachment'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  $ct=$e.Current.ControlType.ProgrammaticName
  $name=[string]$e.Current.Name
  if(($ct -match 'Button|Edit|Text|Image') -and $name){
    $r=$e.Current.BoundingRectangle
    if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 350 -and $r.Y -lt 850){
      $out += [pscustomobject]@{
        type=$ct;name=$name;aid=[string]$e.Current.AutomationId;
        x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height;
        enabled=[bool]$e.Current.IsEnabled
      }
    }
  }
}
[pscustomobject]@{attachment_submit=$true;controls=$out}|ConvertTo-Json -Depth 6 -Compress
